   "code": "def node_label(node: Node, style: str = \"full\") -> str:\n    c, fn = node.ctx, node.func.render(style)\n    if c.merged:\n        return f\"{fn}[*]\"\n    if not c.params:\n        return fn\n    parts = \", \".join(\n        f\"{n}={{{','.join(sorted({token_label(t, style) for t in toks}))}}}\" for n, toks in c.params)\n    return f\"{fn}[{parts}]\"",
